import numpy as np
# Normalize each spectrum by the max intensity in the G band range (1550-1620 cm-1)
g_mask = (x >= 1550) & (x <= 1620)
if np.any(g_mask):
    g_max = np.max(y1[g_mask])
    if g_max > 0:
        y1 = y1 / g_max
    else:
        y1 = y1 * 0
else:
    # Fallback to global max if G band is not found in range
    y1 = y1 / np.max(y1)
